import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Navbar from './components/Navbar';
import HomePage from './pages/HomePage';
import ProductListPage from './pages/ProductListPage';
import ProductDetailPage from './pages/ProductDetailPage';
import CartPage from './pages/CartPage';
import CheckoutPage from './pages/CheckoutPage';
import LoginPage from './pages/LoginPage';
import OrdersPage from './pages/OrdersPage';
import { getOrders, loginUser, placeOrder } from './services/api';

function App() {
    // State management
    const [cart, setCart] = useState([]); // Initialize cart as an empty array
    const [user, setUser] = useState(null); // User state
    const [orders, setOrders] = useState([]); // Orders state
    const [isLoading, setIsLoading] = useState(false); // Loading state for orders

    // Handle user login
    const handleLogin = async (email, password) => {
        try {
            const userData = await loginUser(email, password); // Login API call
            setUser(userData); // Set user in state
            localStorage.setItem('token', userData.token); // Save token to localStorage
        } catch (error) {
            console.error('Error logging in:', error.message);
        }
    };

    // Handle user logout
    const handleLogout = () => {
        setUser(null); // Clear user state
        setCart([]); // Clear the cart on logout
        localStorage.removeItem('token'); // Remove token from localStorage
    };

    // Fetch orders for the logged-in user
    useEffect(() => {
        const fetchUserOrders = async () => {
            if (user) {
                setIsLoading(true);
                try {
                    const fetchedOrders = await getOrders(); // Fetch orders API call
                    setOrders(fetchedOrders); // Set orders in state
                } catch (error) {
                    console.error('Error fetching orders:', error.message);
                } finally {
                    setIsLoading(false); // Reset loading state
                }
            }
        };

        fetchUserOrders();
    }, [user]);

    // Add item to cart
    const handleAddToCart = (product) => {
        setCart((prevCart) => {
            const existingItem = prevCart.find((item) => item.id === product.id);
            if (existingItem) {
                return prevCart.map((item) =>
                    item.id === product.id
                        ? { ...item, quantity: item.quantity + 1 }
                        : item
                );
            }
            return [...prevCart, { ...product, quantity: 1 }];
        });
    };

    // Clear the cart
    const handleClearCart = () => {
        setCart([]); // Reset the cart state
        console.log('Cart cleared successfully.');
    };

    // Place order
    const handlePlaceOrder = async () => {
        try {
            const orderData = {
                products: cart.map((item) => ({
                    product: item.id, // Product ID
                    quantity: item.quantity,
                    price: item.price,
                })),
                totalAmount: cart.reduce((sum, item) => sum + item.price * item.quantity, 0),
            };

            await placeOrder(orderData); // API call to place the order
            alert('Order placed successfully!');
            handleClearCart(); // Clear the cart after placing the order
        } catch (error) {
            console.error('Error placing order:', error.message);
            alert('Failed to place order. Please try again.');
        }
    };

    return (
        <Router>
            <Navbar
                user={user}
                cart={cart || []} // Ensure cart is always passed as an array
                onLogout={handleLogout}
            />
            <Routes>
                <Route
                    path="/"
                    element={<HomePage onAddToCart={handleAddToCart} />} // Pass AddToCart functionality
                />
                <Route
                    path="/products"
                    element={<ProductListPage onAddToCart={handleAddToCart} />}
                />
                <Route
                    path="/products/:id"
                    element={<ProductDetailPage onAddToCart={handleAddToCart} />}
                />
                <Route
                    path="/cart"
                    element={
                        <CartPage
                            cart={cart}
                            onClearCart={handleClearCart}
                            onPlaceOrder={handlePlaceOrder} // Pass handlePlaceOrder function
                        />
                    }
                />
                <Route
                    path="/checkout"
                    element={
                        user ? (
                            <CheckoutPage cart={cart} onClearCart={handleClearCart} />
                        ) : (
                            <Navigate to="/login" />
                        )
                    }
                />
                <Route
                    path="/login"
                    element={
                        user ? <Navigate to="/" /> : <LoginPage onLogin={handleLogin} />
                    }
                />
                <Route
                    path="/orders"
                    element={
                        user ? (
                            <OrdersPage orders={orders} isLoading={isLoading} />
                        ) : (
                            <Navigate to="/login" />
                        )
                    }
                />
            </Routes>
        </Router>
    );
}

export default App;
